import {categoryDefinitions,categoryGroups,PRINCIPAL,DEPRECIATION,defaultDeductible,importSpecial} from './categories.mjs';
import {categories,industries,blankPlan,validatePlan,calculate,applyImport,grossMonthly,netMonthly,allocationSchedule,personCost,allocateBurdenPool} from './model.mjs';
import {feeFilePayload} from '../proposals/fee-import.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>n===null?'Not set':n.toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}),mult=n=>n===null?'Not ready':n.toFixed(2)+'×',val=v=>v===null||v===undefined?'':typeof v==='number'?+v.toFixed(6):v;
let plan=null,revision=null,version=0,savedVersion=0,saving=null,saveError='',unit='monthly',filter='all',selectedCost=null,pending=null,reading=false,readError='',feeTarget=null,comparison=null;
const token=()=>sessionStorage.getItem('studioh_v2_session_tab')||localStorage.getItem('studioh_v2_login_session')||'';
async function request(path,opt={}){const r=await fetch(path,{...opt,headers:{Authorization:'Bearer '+token(),...opt.headers},signal:AbortSignal.timeout(90000),cache:'no-store'});if(!r.ok){let d={};try{d=await r.json()}catch{}throw Object.assign(Error(d.error||'Your records could not load. Please sign in again.'),{status:r.status})}return r}
const json=async(path,data)=>{const r=await request(path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});return r.json()};
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000)}
function showError(e){const box=$('#error');box.hidden=false;box.innerHTML='<p>'+esc(e.message||e)+'</p>';if(plan){const download=document.createElement('button');download.textContent='Download current plan';download.onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(plan,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='overhead-plan-'+plan.year+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)};box.append(download);if(e.status===409){const reload=document.createElement('button');reload.textContent='Reload saved plan';reload.onclick=async()=>{if(!confirm('Reload the server plan and discard unsaved edits? Download your current plan first if you want to keep it.'))return;try{const r=await json('/overhead');plan=r.state?validatePlan(r.state):blankPlan();revision=r.revision;version=0;savedVersion=0;saveError='';box.hidden=true;render()}catch(err){showError(err)}};box.append(reload)}}}
function status(){const dirty=version!==savedVersion;$('#save-state').textContent=saveError?'Not saved — retry':saving?'Saving…':dirty?'Unsaved changes':revision?'Saved to your firm':'Not saved yet';$('#save-plan').disabled=!plan||!!saving;$('#save-plan').textContent=saveError?'Retry save':'Save plan';}
async function save(){if(saving)return saving;if(!plan)return;saveError='';saving=(async()=>{do{const v=version,snapshot=validatePlan(plan);const r=await json('/overhead',{state:snapshot,revision});revision=r.revision;savedVersion=v;plan.updated=r.state.updated;}while(savedVersion!==version)})().catch(e=>{saveError=e.message;showError(e);throw e}).finally(()=>{saving=null;status()});status();return saving}
function change(kind){version++;if(kind==='costs')plan.reviewedCosts=false;if(kind==='people')plan.reviewedPeople=false;feeTarget=null;status();if(!saveError)save().catch(()=>{});}
function edit(next,kind){plan=next;change(kind);render()}
const rows=a=>a.map(([k,v])=>`<div class="row"><span>${k}</span><b>${v}</b></div>`).join('');
const input=(label,id,value,attrs='')=>`<label>${label}<input id="${id}" value="${esc(val(value))}" ${attrs}></label>`;
const opts=(selected,extra=false)=>categoryGroups.map(group=>`<optgroup label="${group}">${categoryDefinitions.map(([name,g],i)=>g===group?`<option value="${i}" ${i===selected?'selected':''}>${name}</option>`:'').join('')}</optgroup>`).join('')+(extra?`<optgroup label="Separate from operating costs">${importSpecial.map(([i,n])=>`<option value="${i}" ${i===selected?'selected':''}>${n}</option>`).join('')}</optgroup>`:'');
const hero=(step,title,desc,action='')=>`<div class="hero"><div><div class="eyebrow">${step}</div><h1>${title}</h1><p class="muted">${desc}</p></div><div class="actions">${action}</div></div>`;
const pill=t=>`<span class="pill">${t}</span>`;
function summary(){const m=calculate(plan);return `<aside class="card blue summary">${pill(plan.year+' annual plan · USD')}<h3>Overhead to recover</h3><div class="number">${money(m.overhead/12)}</div><p class="muted">Monthly · ${m.unknown?m.unknown+' amounts missing':'Known planning costs'}</p>${rows([['Operating costs',money(m.other/12)],['Non-billable payroll · derived',money(m.indirect/12)],['Of which owner time',money(m.ownerIndirect/12)],['Debt principal · cash only',money(m.principal/12)]])}<div class="subhead">Target / burdened direct labour</div><div class="number small">${mult(m.multiplier)}</div><p class="muted">${m.complete?'Includes '+plan.margin+'% target operating margin.':'Review all costs, pay, burden and billable time to calculate a target.'}</p><a class="btn primary" href="#people">People & capacity →</a><div class="note">Private planning data. Owner imputed compensation is an economic cost, not recorded cash payroll.</div></aside>`}
function expenseMembers(c){return plan.costs.filter(x=>x.groupId===c.groupId)}
function expenseHeading(c){const members=expenseMembers(c),g=plan.costGroups.find(g=>g.id===c.groupId);return `<div class="subexpense-heading"><label>Category name<input data-group-name="${esc(g.id)}" value="${esc(g.name)}" required maxlength="150"></label><div class="cost-net"><small>Business cost / month · total of items</small><strong>${money(members.reduce((sum,x)=>sum+(netMonthly(x)??0),0))}</strong></div><div class="subexpense-list">${members.map(x=>`<button data-select-cost="${esc(x.id)}" aria-pressed="${x.id===c.id}" class="${x.id===c.id?'active':''}"><span>${esc(x.name)}</span><b>${netMonthly(x)===null?'Enter amount':money(netMonthly(x))}</b></button>`).join('')}</div><button data-add-sub="${esc(c.id)}">+ Add item</button><p class="muted">This category has no separate charge. Its total is the business share of its items.${members.some(x=>netMonthly(x)===null)?' Items without an amount are excluded from the subtotal.':''}</p>${g.legacy?.some(x=>x.notes||x.documentId)?`<details><summary>Previous category notes</summary>${g.legacy.map(x=>`<p>${esc(x.notes)}</p>${x.documentId?`<button data-download="${esc(x.documentId)}">Source report</button>`:''}`).join('')}</details>`:''}</div>`}
function costsView(){
 unit='monthly';const list=plan.costs.filter(c=>filter==='all'||c.category===+filter);if(!list.some(c=>c.id===selectedCost))selectedCost=list[0]?.id||null;
 const c=list.find(c=>c.id===selectedCost),m=calculate(plan);const groups=list.filter((x,i)=>list.findIndex(y=>y.groupId===x.groupId)===i);
 return hero('01 / ENTER COSTS','Your monthly operating costs.','Enter the full cost, then the share used by your firm.',`<button class="primary" data-add>+ Add expense</button>`)+`
 <div class="cost-plan-fields"><label>Firm industry<select id="industry"><option value="">Choose your industry</option>${industries.map(n=>`<option ${plan.industry===n?'selected':''}>${esc(n)}</option>`).join('')}</select></label>${input('Plan year','year',plan.year,'type="number" min="2000" max="2100" required')}</div>
 <div class="cost-total-strip"><div><small>Operating overhead / month</small><strong>${money(m.other/12)}</strong></div><div><small>Stops with this business</small><strong>${money((m.other-m.committed)/12)}</strong></div><div><small>Continues without it</small><strong>${money(m.committed/12)}</strong></div></div>
 <div class="toolbar cost-controls"><div><h2>Operating expenses</h2><small>Business share · USD · ${list.length} expenses</small></div><div class="actions"><button data-cost-help>ⓘ Cost types</button><a href="#import" class="btn">Import report</a></div></div>
 <div class="cost-workspace"><section class="card cost-list-panel"><label>Category<select id="filter"><option value="all">All categories</option>${opts(filter==='all'?-1:+filter)}</select></label><div class="cost-list">${groups.map(x=>`<button class="cost-choice ${expenseMembers(x).some(y=>y.id===selectedCost)?'selected':''}" data-select-cost="${esc(x.id)}" aria-pressed="${expenseMembers(x).some(y=>y.id===selectedCost)}"><span><strong>${esc(x.expenseGroup||x.name)}</strong><small>${categories[x.category]}</small><span class="cost-meta"><span>${x.expenseGroup?expenseMembers(x).length+(expenseMembers(x).length===1?' item':' items'):x.avoidability==='committed'?'Continues without business':'Stops with business'}</span><small>${x.expenseGroup?'Individual business shares':(x.businessPct??100)+'% business'}${x.category===PRINCIPAL?' · Cash only':''}</small></span></span><b>${money(expenseMembers(x).reduce((n,y)=>n+(netMonthly(y)??0),0))}</b></button>`).join('')||'<p>No expenses in this category.</p>'}</div><button data-add>+ Add expense</button></section>
 <section class="card cost-editor">${c?`${expenseHeading(c)}<div class="cost-editor-fields"><label class="wide">Item name<input data-inline-cost="name" data-id="${esc(c.id)}" value="${esc(c.name)}" required maxlength="150"></label><label>Gross monthly · USD<input aria-label="${esc(c.name)} monthly amount" data-cost="${esc(c.id)}" type="number" min="-1000000000" max="1000000000" step="any" placeholder="Not set" value="${val(grossMonthly(c))}"></label><label>Used by this business · %<input aria-label="${esc(c.name)} business percentage" data-pct="${esc(c.id)}" type="number" min="0" max="100" step="1" required value="${c.businessPct??100}"><small data-pct-error="${esc(c.id)}" class="error" role="alert"></small></label></div><label>Would this cost continue without this business?</label><div class="segmented cost-avoidability">${['avoidable','committed'].map(v=>`<button data-avoid="${esc(c.id)}" data-value="${v}" aria-pressed="${(c.avoidability||'avoidable')===v}" class="${(c.avoidability||'avoidable')===v?'active':''}">${v==='avoidable'?'No':'Yes'}</button>`).join('')}</div><div class="cost-net"><small>${c.category===PRINCIPAL?'Business cash requirement / month':'Business cost / month'}</small><strong>${money(netMonthly(c))}</strong></div><label>Allocation note<input data-inline-cost="notes" data-id="${esc(c.id)}" value="${esc(c.notes||'')}" maxlength="1000" placeholder="How you determined the business share"></label>${(c.businessPct??100)<100&&!c.notes?.trim()?'<p class="error">Basis not documented. Add the reason for this business percentage.</p>':''}<label class="check"><input data-deductible="${esc(c.id)}" type="checkbox" ${c.deductible?'checked':''} ${c.category===PRINCIPAL?'disabled':''}>Include in tax-review schedule</label><p class="muted">${c.category===PRINCIPAL?'Debt principal is cash only and excluded from the billing rate.':'The share used personally or by other businesses is excluded from this firm’s overhead.'}</p><div class="actions"><button data-edit="${esc(c.id)}">Category, frequency & more</button></div>`:'<h2>Add your first expense</h2><p>Enter rent, software or another firm cost to begin.</p><button data-add>+ Add expense</button>'}</section></div><div class="section"><article class="card"><div class="note"><b>Non-billable payroll · computed in People</b><div class="row"><span>Locked derived amount / month</span><b>${money(calculate(plan).indirect/12)}</b></div><a href="#people">Edit People & capacity →</a></div><div class="bottom"><button data-add>+ Add another cost</button></div><div class="section">${rows([['Operating overhead / month',money(calculate(plan).other/12)],['Non-billable payroll / month · from People',money(calculate(plan).indirect/12)],['Total rate-recovery overhead / month',money(calculate(plan).overhead/12)],['Debt principal / month · cash only',money(calculate(plan).principal/12)],['Avoidable overhead incl. non-billable payroll / month',money(calculate(plan).avoidableOverhead/12)],['Committed / month',money(calculate(plan).committed/12)]])}<p class="muted">Business shares only. Non-billable payroll is a locked total computed in People & capacity; it is counted once. Debt principal never enters the billing rate.</p><label>Allocation schedule view<select id="schedule-view"><option value="all">All cost allocations</option><option value="tax">Tax-review selection only</option></select></label><div class="actions"><button data-schedule="csv">Allocation schedule · CSV</button><button data-schedule="pdf">Print / PDF</button></div></div><label class="check section"><input type="checkbox" id="review-costs" ${plan.reviewedCosts?'checked':''}>I reviewed the operating costs for this plan, including any categories with no expenses.</label><p class="muted">Project consultants, reimbursable travel and materials belong to project costs. Payroll is entered once in People.</p></article></div>`}
function costDialog(id,parentId){const c=plan.costs.find(x=>x.id===id)||{name:'',category:parentId?plan.costs.find(x=>x.id===parentId).category:filter==='all'?0:+filter,grossMonthly:null,businessPct:100,avoidability:'avoidable',deductible:true,nonCash:false,notes:''};$('#dialog').innerHTML=`<div class="top"><h2>${id?'Edit item':parentId?'Add item':'Add expense category'}</h2><button data-close>Close</button></div><form id="cost-form">${!id&&!parentId?input('Category name','group-name','','required maxlength="150" placeholder="e.g. Design software"'):''}${input('Item name','cname',c.name,'required maxlength="150" placeholder="e.g. Adobe subscription"')}<label>Category<select id="ccategory">${opts(c.category)}</select></label><div class="grid two">${input('Gross amount · USD','camount',grossMonthly(c),'type="number" min="-1000000000" max="1000000000" step="any" placeholder="Not set"')}${input('Used by this business · %','cpct',c.businessPct??100,'type="number" min="0" max="100" step="1" required')}</div><label>Amount covers<select id="cfreq"><option value="12">One month</option><option value="4">One quarter</option><option value="1">One year</option></select></label><label>Would this cost continue without this business?<select id="cavoid"><option value="avoidable" ${c.avoidability!=='committed'?'selected':''}>No</option><option value="committed" ${c.avoidability==='committed'?'selected':''}>Yes</option></select></label><label class="check"><input type="checkbox" id="cdeductible" ${c.deductible?'checked':''} ${c.category===PRINCIPAL?'disabled':''}>Include in tax-review allocation schedule</label><label class="check"><input type="checkbox" id="cnoncash" ${c.nonCash||c.category===DEPRECIATION?'checked':''} ${c.category===PRINCIPAL?'disabled':''}>Non-cash expense (for example depreciation)</label><p class="muted">This is a review selection, not a tax deduction determination. Entertainment is excluded by default. Debt principal is cash only; interest remains a cost. <a href="https://www.irs.gov/publications/p463" target="_blank" rel="noopener">IRS expense guidance</a></p><p class="error" id="cost-error" role="alert"></p><label>Allocation basis / notes<textarea id="cnotes" maxlength="2000">${esc(c.notes)}</textarea></label>${c.documentId?`<button type="button" data-download="${c.documentId}">Download source report</button>`:''}<p class="muted">Use a negative amount for an expense credit. Leave an unknown amount blank.</p><div class="bottom">${id?'<button type="button" id="remove-cost">Remove cost</button>':'<span></span>'}<button class="primary" type="submit">Save cost</button></div></form>`;$('#dialog').showModal();if(parentId)$('#ccategory').disabled=true;$('#ccategory').onchange=()=>{const cat=+$('#ccategory').value;$('#cdeductible').checked=defaultDeductible(cat);$('#cdeductible').disabled=cat===PRINCIPAL;$('#cnoncash').checked=cat===DEPRECIATION;$('#cnoncash').disabled=cat===PRINCIPAL};$('#cfreq').onchange=()=>{$('#camount').value=$('#camount').value===''?'':(+$('#camount').value*(+$('#cfreq').dataset.previous||12)/+$('#cfreq').value);$('#cfreq').dataset.previous=$('#cfreq').value};$('#cost-form').onsubmit=e=>{e.preventDefault();const name=$('#cname').value.trim();if(!name)return;const parent=plan.costs.find(x=>x.id===parentId);const next={id:id||crypto.randomUUID(),name,expenseGroup:parent?parent.expenseGroup:(c.expenseGroup||$('#group-name')?.value.trim()||name),groupId:parent?.groupId||c.groupId||null,category:+$('#ccategory').value,grossMonthly:$('#camount').value===''?null:+$('#camount').value*+$('#cfreq').value/12,businessPct:+$('#cpct').value,avoidability:$('#cavoid').value,deductible:$('#cdeductible').checked,nonCash:$('#cnoncash').checked,notes:$('#cnotes').value,source:c.source||'Manual',documentId:c.documentId||null};const i=plan.costs.findIndex(x=>x.id===id);const candidate=structuredClone(plan);if(id&&next.groupId){candidate.costGroups.find(g=>g.id===next.groupId).category=next.category;candidate.costs.filter(x=>x.groupId===next.groupId).forEach(x=>x.category=next.category)}if(parent){candidate.costs.find(x=>x.id===parentId).expenseGroup=next.expenseGroup;next.category=parent.category}if(i<0)candidate.costs.push(next);else candidate.costs[i]=next;try{plan=validatePlan(candidate)}catch(err){$('#cost-error').textContent=err.message;return}selectedCost=next.id;$('#dialog').close();change('costs');render()};$('#remove-cost')?.addEventListener('click',()=>{const target=plan.costs.find(c=>c.id===id);if(expenseMembers(target).length===1){target.name='Item 1';target.grossMonthly=null;target.businessPct=100;target.notes='';target.documentId=null;target.source='manual'}else plan.costs=plan.costs.filter(c=>c.id!==id);plan=validatePlan(plan);$('#dialog').close();change('costs');render()});bindDialog()}
function peopleView(){const m=calculate(plan);return hero('03 / PEOPLE & CAPACITY','Include the time you can’t bill.','Enter pay, employer burden and the share of paid time expected to be billable. Payroll taxes, workers compensation and benefits belong here.',`<button data-owner>+ Add owner</button><button data-person>+ Add role</button>`)+`<div class="card section"><div class="grid two">${input('Default employer burden · % (optional)','default-burden',plan.defaultBurdenPct,'type="number" min="0" max="200" step="any" placeholder="e.g. 20–30%; verify your own costs"')}<p class="muted">Include employer FICA/FUTA/SUTA, workers compensation, health insurance and retirement contributions. Use your own payroll figures. Each person can override this default. Payroll processing and HR software stay in operating costs.</p></div>${plan.burdenNeedsReview||plan.unallocatedBurden>0?`<div class="note"><b>Employer costs need allocation: ${money(plan.unallocatedBurden)} / year</b><p>Imported totals are not added on top of person percentages. Allocate this total across paid wages to replace their burden percentages, or enter each person’s rate and confirm the review below.</p><button id="allocate-burden">Allocate across paid wages</button><p id="burden-error" class="error"></p></div>`:''}</div><div class="grid workspace section"><article class="card"><h2>People in your annual plan</h2>${plan.people.map(p=>{const c=personCost(p,plan.defaultBurdenPct),control=(label,key,value,attrs='')=>`<label>${label}<input data-person-field="${key}" data-person-id="${p.id}" value="${esc(val(value))}" ${attrs}></label>`;return `<section class="person-card"><div class="toolbar"><b>${p.owner?'Owner':'Team member'}${p.compensation==='imputed'?' · imputed compensation':''}</b><button data-remove-person="${p.id}">Remove</button></div><div class="grid two">${control('Name / role','name',p.name,'required maxlength="150"')}<label>Role type<select data-person-field="owner" data-person-id="${p.id}"><option value="false" ${!p.owner?'selected':''}>Employee</option><option value="true" ${p.owner?'selected':''}>Working owner</option></select></label><label>Pay basis<select data-person-field="wageBasis" data-person-id="${p.id}"><option value="annual" ${p.wageBasis==='annual'?'selected':''}>Annual compensation</option><option value="hourly" ${p.wageBasis==='hourly'?'selected':''}>Hourly pay</option></select></label>${control(p.wageBasis==='hourly'?'Base pay / hour · USD':'Base annual compensation · USD','baseWage',p.baseWage,'type="number" min="0" max="1000000000" step="any" placeholder="Not set"')}${p.wageBasis==='hourly'?control('Paid hours / year','hoursPerYear',p.hoursPerYear,'type="number" min="0" max="8784" step="any" placeholder="Not set"'):''}${p.owner?`<label>Owner compensation<select data-person-field="compensation" data-person-id="${p.id}"><option value="paid" ${p.compensation==='paid'?'selected':''}>Paid compensation / planned draw</option><option value="imputed" ${p.compensation==='imputed'?'selected':''}>Imputed market salary · not paid</option></select></label>`:''}${control('Employer burden override · %','burdenPct',p.burdenPct,'type="number" min="0" max="200" step="any" placeholder="Use firm default (if set)"')}${control('Billable target · %','billableTargetPct',p.billableTargetPct,'type="number" min="0" max="100" step="any" placeholder="Not set"')}</div>${p.owner?'<p class="muted">If you do not pay a formal wage, choose imputed market salary and enter replacement compensation. It feeds the sustainable target, while the cash view excludes unpaid compensation.</p>':''}${rows([['Burdened annual compensation',money(c.ready?c.cost:null)],['Direct billable labour / year',money(c.ready?c.direct:null)],['Non-billable labour / month',money(c.ready?c.indirect/12:null)]])}</section>`}).join('')||'<p>Add staff and a working owner to model capacity.</p>'}<div class="actions"><button data-person>+ Add role</button><button data-owner>+ Add owner</button></div><label class="check section"><input id="review-people" type="checkbox" ${plan.reviewedPeople?'checked':''}>I reviewed compensation, burden and billable shares. My per-person burden rates include all employer costs.</label><p class="muted">Totals show known inputs only; an incomplete person prevents a recommendation. A blank burden requires a firm default. Enter an explicit 0 only when no employer burden applies.</p></article><aside class="card blue summary"><h3>Owner non-billable time</h3><div class="number">${money(m.ownerIndirect/12)}</div><p class="muted">Per month of firm overhead · ${money(m.imputedIndirect/12)} is imputed.</p>${rows([['Base annual pay',money(m.payroll)],['Burdened annual pay',money(m.burdenedPayroll)],['Burdened direct labour',money(m.direct)],['Non-billable payroll · overhead',money(m.indirect)]])}<p class="note">Payroll is counted once. Non-billable costs flow to Enter costs as a locked derived total.</p><a class="btn primary" href="#target">Review target →</a></aside></div>`}
function importView(){return hero('02 / ASSISTED IMPORT','From report to reviewed costs.','Original reports remain private to your firm. AI prepares suggestions; nothing enters your plan until you review and apply it.')+(pending?importReview():`<div class="grid two"><article class="card"><h2>Upload a P&L or expense report</h2><p class="muted">PDF, Excel XLSX or CSV · maximum 4 MB. A full-year expense summary works best.</p><div class="drop"><h3>Choose your report</h3><input id="report-file" type="file" aria-label="Choose a P&L report" accept=".pdf,.xlsx,.csv" ${reading?'disabled':''}></div><p class="muted section">Your original file is saved privately to your firm. When you click Read report, PDFs or extracted spreadsheet cells are sent to the app’s AI service for classification.</p><button id="read-report" class="primary" ${reading?'disabled':''}>${reading?'Reading report…':'Read report →'}</button><p role="status" class="section ${readError?'error':''}">${esc(readError|| (reading?'This may take a minute. You can keep this page open.':''))}</p></article><article class="card blue">${pill('Review before applying')}<h2 class="section">A first pass you can inspect.</h2><ol class="flat-list"><li>Read report dates, accounts and totals.</li><li>Suggest expense categories with source references.</li><li>Keep payroll and direct project costs separate.</li><li>Review every amount and resolve mixed accounts.</li><li>Replace only the selected categories in your plan.</li></ol><p class="muted">A P&L cannot tell us staff project-time shares, future staffing or your desired margin. Enter those in People & capacity and Review your target.</p></article></div>`)+`<article class="card section"><h2>Applied source reports</h2>${plan.imports.length?plan.imports.map(r=>`<div class="row"><span><b>${esc(r.name)}</b><br><small>${esc(r.from)} – ${esc(r.to)} · ${esc(r.basis)}</small></span><button data-download="${r.id}">Download source</button></div>`).join(''):'<p class="muted">Reviewed reports appear here after applying their costs. Re-importing the same file is blocked to prevent duplicates.</p>'}</article>`}
function importReview(){const p=pending,x=p.extracted,used=x.lines.filter(l=>l.include&&(l.category<categories.length||l.category===100)),total=used.reduce((a,l)=>a+(l.amount??0),0);return `<div class="notice"><b>${esc(p.name)}</b> · ${x.lines.length} extracted accounts. Check all figures against the original.<button data-download="${p.id}">View source</button></div>${x.notes.map(n=>`<p class="note">${esc(n)}</p>`).join('')}<article class="card"><div class="grid two">${input('Report starts','report-from',x.from,'type="date" required')}${input('Report ends','report-to',x.to,'type="date" required')}<label>Accounting basis<select id="report-basis">${['Unknown','Cash','Accrual'].map(n=>`<option ${x.basis===n?'selected':''}>${n}</option>`).join('')}</select></label><label>Report currency<select id="report-currency"><option value="">Confirm currency</option><option ${x.currency==='USD'?'selected':''}>USD</option></select></label></div><label class="check"><input type="checkbox" id="annualize" ${p.annualize?'checked':''}>For a partial year, annualize the selected expenses using report days. I will review seasonal and one-off costs.</label></article><article class="card mapping section"><h2>Source → proposed costs</h2><table><thead><tr><th>Use</th><th>Source account</th><th>Period amount · USD</th><th>Proposed category</th></tr></thead><tbody>${x.lines.map((l,i)=>`<tr><td><input type="checkbox" aria-label="Include ${esc(l.name)}" data-include="${i}" ${l.include?'checked':''}></td><td><b>${esc(l.name)}</b><small>Source amount: ${money(l.sourceAmount)}</small><small>${esc(l.evidence)}</small>${l.note?`<small>${esc(l.note)}</small>`:''}</td><td><input aria-label="${esc(l.name)} amount" data-import-amount="${i}" type="number" min="-1000000000" max="1000000000" step="any" placeholder="Not set" value="${val(l.amount)}"></td><td><select aria-label="${esc(l.name)} category" data-map="${i}">${opts(l.category,true)}</select></td></tr>`).join('')}</tbody></table></article><article class="card blue section"><h3>Selected period costs: ${money(total)}</h3><p class="muted">${used.length} overhead / benefit lines. Payroll and project expenses remain separate. Selected categories will replace their current plan values; other categories are retained.</p><label class="check"><input id="confirm-import" type="checkbox" ${p.confirmed?'checked':''}>I checked the source figures, dates, currency and category mappings. Replace the selected categories in my plan.</label><div class="bottom"><button id="cancel-import">Cancel review</button><button id="apply-import" class="primary" ${!p.confirmed||!used.length?'disabled':''}>Apply reviewed costs →</button></div><p class="error" id="import-error" role="alert"></p></article>`}
function targetView(){const m=calculate(plan);return hero('04 / REVIEW & RECOMMENDATION','A target built from your costs.','Multipliers below use burdened direct labour. The fee-book update converts the target to its direct-pay basis.')+`<div class="grid two"><article class="card blue">${pill('Sustainable target · includes owner time')}<div class="target-stat"><strong class="big">${mult(m.multiplier)}</strong></div>${rows([['Full-cost break-even',mult(m.breakEven)],['Avoidable-cost floor',mult(m.floor)],['Target without imputed owner non-billable time',mult(m.withoutImputedOwner)],['Break-even without that imputed time',mult(m.breakEvenWithoutImputedOwner)]])}<p class="muted">The comparison removes only unpaid, imputed owner non-billable time. Paid owner compensation stays included. Both use the same burdened direct-labour denominator.</p>${input('Target operating margin · %','margin',plan.margin,'type="number" min="0" max="60" required')}<p class="note">The avoidable-cost floor excludes committed operating costs and profit. It retains planned payroll and is not an incremental cash-cost guarantee for an individual job.</p><button id="use-target" class="primary" ${!m.complete?'disabled':''}>Review fee-book update →</button>${feeTarget?`<p class="section">Fee-book direct-pay target updated to ${feeTarget.toFixed(2)}×.</p>`:''}</article><article class="card"><h2>Where the money goes</h2>${rows([['Burdened direct labour / year',money(m.direct)],['Non-billable payroll / year · counted once',money(m.indirect)],['Owner non-billable time / month',money(m.ownerIndirect/12)],['Operating overhead / year',money(m.other)],['Overhead to recover in the rate / month',money(m.overhead/12)],['Debt principal / month · cash only',money(m.principal/12)],['Cash to cover each month',money(m.cashAnnual===null?null:m.cashAnnual/12)]])}<p class="muted">Cash coverage includes paid payroll, cash operating costs and debt principal. It excludes imputed owner pay and marked non-cash expenses. It is a planning requirement, not a bank balance forecast.</p><div class="actions"><a class="btn" href="#costs">Edit costs</a><a class="btn" href="#people">Edit people</a></div><p class="note">Costs ${plan.reviewedCosts?'reviewed':'need review'} · People ${plan.reviewedPeople?'reviewed':'need review'}. ${m.complete?'': 'Complete all unknown inputs and review both steps to calculate recommendations.'}</p></article></div><div class="grid two section"><article class="card"><h3>Net service revenue needed</h3><div class="number">${money(m.target===null?null:m.target/12)}</div><p class="muted">Monthly · ${money(m.target)} annually, including target margin</p></article><article class="card"><h3>Target operating profit</h3><div class="number">${money(m.target===null?null:(m.target-m.total)/12)}</div><p class="muted">Monthly · after all planned operating costs and owner compensation, before income tax</p></article></div>${capacityPanel(m)}<p class="note">Private firm financial information · kept out of client proposals. Applying a multiplier changes future fee planning only.</p>`}
async function readReport(){const file=$('#report-file')?.files[0];if(!file){readError='Choose a report first.';render();return}reading=true;readError='';render();try{const payload=await feeFilePayload(file),bytes=await file.arrayBuffer(),digest=await crypto.subtle.digest('SHA-256',bytes),id=[...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');if(plan.imports.some(i=>i.id===id))throw Error('This file has already been applied. Edit the existing costs or choose a different report.');const mime=/\.pdf$/i.test(file.name)?'application/pdf':/\.csv$/i.test(file.name)?'text/csv':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';await request('/overhead/reports/'+id,{method:'PUT',headers:{'Content-Type':mime},body:bytes});const result=await json('/overhead/import',{documentId:id,...(payload.format==='text'?{text:payload.data}:{})});pending={id,name:file.name,extracted:result.extracted,annualize:false,confirmed:false};}catch(e){readError=e.message}finally{reading=false;render()}}
async function download(id){try{const r=await request('/overhead/reports/'+id),blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=plan.imports.find(i=>i.id===id)?.name||pending?.name||'source-report';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}catch(e){showError(e)}}
async function reviewTarget(){try{await save();const f=await json('/financials/defaults'),m=calculate(plan),planRevision=revision;$('#dialog').innerHTML=`<div class="top"><h2>Update future fee planning</h2><button data-close>Close</button></div>${rows([['Current fee-book multiplier',f.state?.feeBook?.multiplier?mult(f.state.feeBook.multiplier):'Not set'],['Recommended · burdened direct labour',mult(m.multiplier)],['Equivalent fee-book target · direct pay',mult(m.directPayMultiplier)],['Plan year',plan.year]])}<p class="note">The fee book divides fees by base direct pay. This equivalent target preserves the same revenue target after employer burden. This changes only the studio fee-book multiplier. Service prices, allowance overrides, existing proposals and signed work remain unchanged.</p><button class="primary section" id="confirm-target">Use ${mult(m.directPayMultiplier)} for future planning</button><p id="target-error" class="error" role="alert"></p>`;$('#dialog').showModal();bindDialog();$('#confirm-target').onclick=async()=>{const b=$('#confirm-target');b.disabled=true;try{const r=await json('/overhead/target',{revision:planRevision,feeRevision:f.revision,confirmed:true});feeTarget=r.multiplier;$('#dialog').close();render();toast('Studio fee-book target updated.')}catch(e){$('#target-error').textContent=e.message;b.disabled=false}}}catch(e){showError(e)}}
function render(){if(!plan)return;const page=location.hash.slice(1)||'costs';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));$('#view').innerHTML=page==='import'?importView():page==='people'?peopleView():page==='target'?targetView():costsView();if(plan.sampleLabel)$('#view').insertAdjacentHTML('afterbegin','<div class="card" style="margin-bottom:24px"><strong>'+esc(plan.sampleLabel)+'</strong><p>Fictional costs for exploring the developer account. Replace these with your own records before using the recommendation.</p></div>');if(plan.migration&&!plan.migration.acknowledged)$('#view').insertAdjacentHTML('afterbegin',migrationNotice());bind();status()}
function bindDialog(){document.querySelectorAll('#dialog [data-close]').forEach(b=>b.onclick=()=>$('#dialog').close());document.querySelectorAll('#dialog [data-download]').forEach(b=>b.onclick=()=>download(b.dataset.download))}
function bind(){document.querySelectorAll('[data-group-name]').forEach(e=>e.onchange=()=>{if(!e.reportValidity())return;const group=plan.costGroups.find(g=>g.id===e.dataset.groupName);group.name=e.value.trim();plan.costs.filter(c=>c.groupId===group.id).forEach(c=>c.expenseGroup=group.name);change('costs');render()});document.querySelectorAll('[data-add-sub]').forEach(b=>b.onclick=()=>costDialog(null,b.dataset.addSub));
 document.querySelectorAll('[data-select-cost]').forEach(b=>b.onclick=()=>{selectedCost=b.dataset.selectCost;render()});
 document.querySelectorAll('[data-inline-cost]').forEach(e=>e.onchange=()=>{if(!e.reportValidity())return;const c=plan.costs.find(x=>x.id===e.dataset.id);c[e.dataset.inlineCost]=e.value.trim();change('costs');render()});
 $('#ack-migration')?.addEventListener('click',()=>{plan.migration.acknowledged=true;change();render()});
 document.querySelectorAll('[data-deductible]').forEach(e=>e.onchange=()=>{plan.costs.find(c=>c.id===e.dataset.deductible).deductible=e.checked;change('costs');render()});
 for(const id of ['capacity-wage','capacity-hours'])$('#'+id)?.addEventListener('input',()=>{const m=calculate(plan),w=+$('#capacity-wage').value,h=+$('#capacity-hours').value,rate=m.multiplier*w,contribution=rate-w;$('#capacity-result').innerHTML=m.complete&&w>0&&h>0&&contribution>0?rows([['Implied target fee / hour',money(rate)],['Avoidable-cost floor / hour',money(m.floor*w)],['Hours / month covering committed operating costs',(m.committed/12/contribution).toFixed(1)],['Hours / month covering all overhead',(m.overhead/12/contribution).toFixed(1)],['Planned billable hours / month',(h*m.direct/m.burdenedPayroll).toFixed(1)],['Utilization needed · committed',(m.committed/12/contribution/h*100).toFixed(1)+'%'],['Utilization needed · full overhead',(m.overhead/12/contribution/h*100).toFixed(1)+'%'],['Planned cost-weighted utilization',(m.direct/m.burdenedPayroll*100).toFixed(1)+'%']])+'<p>Uses fee less burdened direct labour cost per hour to recover overhead. Assumes all target hours are sold at the target rate; outside project costs need separate fee recovery.</p>':'Complete the reviewed plan and enter positive wage and hour values.'});
 document.querySelectorAll('[data-cost-help]').forEach(b=>b.onclick=()=>{$('#dialog').innerHTML='<div class="top"><h2>Two ways to view your costs</h2><button data-close>Close</button></div><h3>Avoidable</h3><p>Costs that stop when the firm stops operating, such as cancellable software or marketing. Consider notice periods and contractual commitments.</p><h3>Committed</h3><p>Costs you would still pay, such as the business share of your home rent or a personal vehicle lease. A dedicated business lease may also be committed until it ends.</p><p>Business use and avoidability are separate. Only the business percentage enters the firm plan. These are management allocations, not a determination of tax deductibility.</p><p>Both scenarios keep planned wages and employer costs. The floor excludes tagged committed operating costs and profit; it is not a guaranteed incremental cash-cost floor for a particular job.</p>';$('#dialog').showModal();bindDialog()});
 document.querySelectorAll('[data-pct]').forEach(e=>{e.oninput=()=>{const valid=e.value!==''&&e.validity.valid;document.querySelector('[data-pct-error="'+e.dataset.pct+'"]').textContent=valid?'':'Enter a whole percentage from 0 to 100.';e.setAttribute('aria-invalid',String(!valid))};e.onchange=()=>{if(!e.reportValidity())return;plan.costs.find(c=>c.id===e.dataset.pct).businessPct=+e.value;change('costs');render()}});
 document.querySelectorAll('[data-avoid]').forEach(b=>b.onclick=()=>{plan.costs.find(c=>c.id===b.dataset.avoid).avoidability=b.dataset.value;change('costs');render()});
 document.querySelectorAll('[data-schedule]').forEach(b=>b.onclick=()=>exportSchedule(b.dataset.schedule));
document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>costDialog());document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>costDialog(b.dataset.edit));document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{unit=b.dataset.unit;render()});$('#filter')?.addEventListener('change',e=>{filter=e.target.value;render()});document.querySelectorAll('[data-cost]').forEach(e=>e.onchange=()=>{if(!e.reportValidity())return;const c=plan.costs.find(c=>c.id===e.dataset.cost);c.grossMonthly=e.value===''?null:+e.value/(unit==='monthly'?1:12);change('costs');render()});for(const [id,key,kind] of [['industry','industry',null],['year','year',null],['margin','margin',null]])$('#'+id)?.addEventListener('change',e=>{if(!e.target.reportValidity())return;plan[key]=id==='industry'?e.target.value:e.target.value===''?null:+e.target.value;change(kind);render()});for(const [id,key] of [['review-costs','reviewedCosts'],['review-people','reviewedPeople']])$('#'+id)?.addEventListener('change',e=>{plan[key]=e.target.checked;if(key==='reviewedPeople'&&e.target.checked){plan.burdenNeedsReview=false;plan.unallocatedBurden=0}change();render()});document.querySelectorAll('[data-person],[data-owner]').forEach(b=>b.onclick=()=>{const owner=b.hasAttribute('data-owner');plan.people.push({id:crypto.randomUUID(),name:owner?'Working owner':'New role',baseWage:null,wageBasis:'annual',hoursPerYear:null,burdenPct:null,billableTargetPct:null,owner,compensation:owner?'imputed':'paid'});change('people');render()});document.querySelectorAll('[data-remove-person]').forEach(b=>b.onclick=()=>{plan.people=plan.people.filter(p=>p.id!==b.dataset.removePerson);change('people');render()});document.querySelectorAll('[data-person-field]').forEach(e=>e.onchange=()=>{if(!e.reportValidity())return;const p=plan.people.find(p=>p.id===e.dataset.personId),key=e.dataset.personField;p[key]=key==='owner'?e.value==='true':['name','compensation','wageBasis'].includes(key)?e.value.trim():e.value===''?null:+e.value;if(!p.owner)p.compensation='paid';change('people');render()});$('#default-burden')?.addEventListener('change',e=>{if(!e.target.reportValidity())return;plan.defaultBurdenPct=e.target.value===''?null:+e.target.value;change('people');render()});$('#allocate-burden')?.addEventListener('click',()=>{try{edit(allocateBurdenPool(plan),'people')}catch(e){$('#burden-error').textContent=e.message}});$('#read-report')?.addEventListener('click',readReport);document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>download(b.dataset.download));if(pending){for(const [id,key] of [['report-from','from'],['report-to','to'],['report-basis','basis'],['report-currency','currency']])$('#'+id)?.addEventListener('change',e=>{pending.extracted[key]=e.target.value;pending.confirmed=false;render()});$('#annualize')?.addEventListener('change',e=>{pending.annualize=e.target.checked;pending.confirmed=false;render()});for(const [attr,key] of [['include','include'],['map','category'],['import-amount','amount']])document.querySelectorAll('[data-'+attr+']').forEach(e=>e.onchange=()=>{if(!e.reportValidity())return;pending.extracted.lines[+e.getAttribute('data-'+attr)][key]=key==='include'?e.checked:e.value===''?null:+e.value;pending.confirmed=false;render()});$('#confirm-import')?.addEventListener('change',e=>{pending.confirmed=e.target.checked;render()});$('#cancel-import')?.addEventListener('click',()=>{pending=null;render()});$('#apply-import')?.addEventListener('click',async()=>{try{if(pending.extracted.currency!=='USD')throw Error('Confirm this is a USD report before applying.');const next=applyImport(plan,pending,pending.extracted.lines.map(l=>({...l,reviewed:pending.confirmed})),{...pending.extracted,annualize:pending.annualize,confirmed:pending.confirmed});edit(next,'costs');await save();pending=null;location.hash='costs';render();toast('Reviewed costs saved. Complete the plan review before using a target.')}catch(e){if($('#import-error'))$('#import-error').textContent=e.message;else showError(e)}})}$('#use-target')?.addEventListener('click',reviewTarget)}
$('#save-plan').onclick=()=>save().then(()=>{$('#error').hidden=true;toast('Plan saved to your firm.')} ).catch(()=>{});$('#project-back').onclick=async e=>{e.preventDefault();try{if(plan&&(saving||savedVersion!==version||saveError))await save();const href=$('#project-back').href;if(!window.studiohNavigateFinancials?.(href))location.href=href}catch{}};window.addEventListener('beforeunload',e=>{if(plan&&savedVersion!==version){e.preventDefault();e.returnValue=''}});window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);if(location.hash==='#target'&&plan)loadComparison()});
async function start(){try{const [session,r]=await Promise.all([json('/session'),json('/overhead')]);if(session.role!=='admin'||session.demo)throw Error('Overhead requires a studio administrator account.');plan=r.state?validatePlan(r.state):blankPlan();revision=r.revision;selectLinkedGroup(location.href);render();document.documentElement.dataset.financeReady='true';window.dispatchEvent(new Event('studioh-finance-ready'));if(location.hash==='#target')loadComparison()}catch(e){$('#view').innerHTML='<div class="card"><h2>Firm overhead</h2><p>'+esc(e.message)+'</p><p>Open Financials from your signed-in Studio H workspace.</p><a class="btn" href="../../">Open workspace</a></div>';$('#save-state').textContent='Unavailable'}}start();

if(new URLSearchParams(location.search).get('return')==='firm'){document.querySelector('#project-back').href='../firm-financials/';document.querySelector('#project-back').textContent='← Back to Firm financials'}

let comparisonLoading=false,comparisonError='',comparisonRequest=null,comparisonSequence=0;
function loadComparison(){const year=plan.year,key=year+':'+version;if(comparisonRequest?.key===key)return comparisonRequest.promise;const sequence=++comparisonSequence;comparisonLoading=true;comparisonError='';refreshComparisonPanel();const promise=json('/firm-financials?view=comparison&year='+year).then(r=>{if(sequence===comparisonSequence&&plan.year===year)comparison=r.comparison}).catch(()=>{if(sequence===comparisonSequence)comparisonError='Comparison could not load. Reopen Review your target to retry.'}).finally(()=>{if(sequence===comparisonSequence){comparisonLoading=false;comparisonRequest=null;refreshComparisonPanel()}});comparisonRequest={key,promise};return promise}
function refreshComparisonPanel(){if(location.hash==='#target'){const panel=document.getElementById('overhead-variance');if(panel)panel.outerHTML=variancePanel()}}
function variancePanel(){if(comparisonLoading||comparisonError)return `<article id="overhead-variance" class="card section"><h2>Plan versus actual operating overhead</h2><p role="status">${comparisonLoading?'Loading comparison…':comparisonError}</p></article>`;const v=comparison?.variance||[];return `<article id="overhead-variance" class="card section"><h2>Plan versus actual operating overhead</h2><p class="muted">Monthly average for reviewed ${plan.year} records: ${comparison?.variancePeriod?.join(', ')||'No reconciled category periods'}. A difference above 10% is flagged. Payroll and employer costs are separate.</p><details class="section"><summary>Category comparison · ${v.filter(r=>r.flag).length} to review</summary><div class="mapping"><table><thead><tr><th>Category</th><th>Plan / month</th><th>Actual / month</th><th>Difference</th></tr></thead><tbody>${v.map(r=>`<tr><td>${r.name}</td><td>${money(r.planned)}</td><td>${money(r.actual)}</td><td class="${r.flag?'error':''}">${money(r.delta)}${r.pct===null?'':` · ${(r.pct*100).toFixed(1)}%`}${r.flag?' · Review':''}</td></tr>`).join('')}</tbody></table></div></details><a href="../firm-financials/?return=overhead">Enter / review actual monthly category costs →</a><p class="muted">Actual records are never inferred from your plan or an annualized import.</p></article>`}
function capacityPanel(m){return `<article class="card section"><h2>Capacity to cover overhead</h2><p>The multiplier is a ratio, not an hourly billing rate. Enter your planned average burdened direct labour cost per billable hour and monthly paid hours to estimate capacity.</p><div class="grid two">${input('Average burdened direct labour cost / billable hour · USD','capacity-wage',null,'type="number" min="0.01" step="any"')}${input('Firm paid hours / month','capacity-hours',null,'type="number" min="0.01" step="any"')}</div><div id="capacity-result" class="note">Scenario only · not saved. Enter both values. Utilization uses the cost-weighted project-time share from People.</div></article>`}
function exportSchedule(format){const tax=$('#schedule-view')?.value==='tax',rows=allocationSchedule(plan,{deductibleOnly:tax}),asOf=new Date().toISOString().slice(0,10),head=['Category','Cost','Gross annual USD','Business %','Net annual USD','Avoidability','Tax-review selection','Non-cash','Note','Source','Basis review'],table=rows.map(r=>[r.category,r.name,r.grossAnnual,r.businessPct,r.netAnnual,r.avoidability,r.deductible?'Included':'Excluded',r.nonCash?'Yes':'No',r.note,r.source,r.basisMissing?'Basis not documented':'']);const privacy='Private firm financial information · kept out of client proposals';const caption=`Overhead allocation schedule · ${tax?'Tax-review selection':'All cost allocations'} · ${plan.year}-01-01 to ${plan.year}-12-31 · as of ${asOf}. Annual planning equivalents, not proof of actual spending or tax deductibility.`;
 if(format==='csv'){const q=v=>'"'+(typeof v==='number'?String(Number(v.toFixed(2))):String(v??'').replace(/^[=+@-]/,"'$&")).replace(/"/g,'""')+'"',content=[[privacy],[caption],head,...table,['Total','',rows.reduce((s,r)=>s+(r.grossAnnual??0),0),'',rows.reduce((n,r)=>n+(r.netAnnual??0),0)]].map(r=>r.map(q).join(',')).join('\r\n'),u=URL.createObjectURL(new Blob([content],{type:'text/csv'})),a=document.createElement('a');a.href=u;a.download='overhead-allocation-'+plan.year+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);return}
 const w=window.open('','_blank');if(!w){toast('Allow the report window to open for Print / PDF.');return}w.document.write('<!doctype html><title>Private overhead allocation schedule</title><style>body{font:12px system-ui;color:#293b34;padding:25px}table{width:100%;border-collapse:collapse}th,td{padding:9px;text-align:left;border-bottom:1px solid #ddd}thead{display:table-header-group}tr{break-inside:avoid}button{padding:12px}@media print{button{display:none}@page{size:landscape;margin:12mm}}</style><h1>Overhead allocation schedule</h1><p>'+esc(privacy)+'</p><p>'+esc(caption)+'</p><button onclick="window.print()">Print / Save as PDF</button><table><thead><tr>'+head.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+table.map(r=>'<tr>'+r.map(v=>'<td>'+esc(v===null?'Unknown':v)+'</td>').join('')+'</tr>').join('')+'</tbody></table><p>Total selected annual allocations: '+money(rows.reduce((n,r)=>n+(r.netAnnual??0),0))+'</p>');w.document.close();
}

function groupCostRows(list,renderRow){return categoryGroups.map(g=>{const items=list.filter(c=>categoryDefinitions[c.category][1]===g);return items.length?`<details class="cost-group" ${items.some(c=>grossMonthly(c)!==0)?'open':''}><summary>${g} <small>${items.length} ${items.length===1?'cost':'costs'}</small></summary>${items.map(renderRow).join('')}</details>`:''}).join('')}
function migrationNotice(){const r=plan.migration;return `<article class="card migration-notice"><h2>Your payroll plan has been upgraded</h2><p>${esc(r.reason)}</p>${rows([['Previous overhead / year',money(r.beforeOverhead)],['Reclassified overhead / year',money(r.afterOverhead)]])}${r.moved.length?`<p>Moved into employer burden: ${r.moved.map(x=>esc(x.name)+' ('+money(x.annual)+'/year)').join(', ')}.</p>`:''}<p class="muted">Employer costs now follow billable and non-billable wages, instead of all sitting in overhead. Existing expense amounts are preserved. Review People & capacity before applying a new target. Mark any existing owner role as Working owner rather than entering that compensation twice.</p><div class="actions"><a class="btn" href="#people">Review people</a><button id="ack-migration">Got it</button></div></article>`}
if(window.self!==window.top)document.body.classList.add('embedded');

// Preserve the live expense editor and optimistic revision when switching areas.
let returnRequest=0,returnInteraction=0;
document.addEventListener('input',()=>returnInteraction++);
document.addEventListener('change',()=>returnInteraction++);
window.addEventListener('studioh-finance-activate',async()=>{
 if(!plan||saving||saveError||version!==savedVersion||$('#dialog').open||document.activeElement?.matches('input,textarea,select,[contenteditable=true]'))return;
 const requestId=++returnRequest,original=plan,edit=returnInteraction,v=version;
 try{const r=await json('/overhead');if(requestId!==returnRequest||plan!==original||version!==v||returnInteraction!==edit||saving||saveError||$('#dialog').open)return;
 if(r.revision!==revision){plan=r.state?validatePlan(r.state):blankPlan();revision=r.revision;comparison=null;render();if(location.hash==='#target')loadComparison()}
 }catch(e){if(requestId!==returnRequest)return;if(e.status===401||e.status===403){plan=null;$('#view').textContent='Sign in with an authorized administrator account to view overhead.';$('#save-plan').disabled=true}showError(e)}
});

function selectLinkedGroup(url){if(!plan)return;const group=new URL(url,location.href).searchParams.get('group');if(!group)return;const item=plan.costs.find(c=>c.groupId===group);if(item){filter='all';selectedCost=item.id;}}
window.addEventListener('studioh-finance-navigate',e=>{selectLinkedGroup(e.detail.url);if(plan)render()});
